const SCREENS={
splash:()=>`<div class="hero-s"><div class="logo lgo"><img class="lg" src="APK_Logo_512x512_Transparent.png" alt=""></div><h1>${esc(appName())}</h1><p class="muted">Tasks that reward you</p><div class="prog" style="width:140px"><i style="width:0;animation:ld 1.6s forwards"></i></div></div><style>@keyframes ld{to{width:100%}}</style>`,
onboard:(i=0)=>{const s=[['🔎','Discover tasks','Browse fresh app, video and social tasks picked for you.'],['🎁','Complete tasks & earn rewards','Follow the steps, submit, and get rewarded after review.'],['💸','Withdraw your eligible balance','Once you reach the minimum, request a payout to your UPI ID.']][i];
 return `<div class="hero-s"><div class="logo ob-ill">${s[0]}</div><h1>${s[1]}</h1><p class="muted" style="max-width:300px">${s[2]}</p><div class="dots">${[0,1,2].map(k=>`<i class="${k===i?'on':''}"></i>`).join('')}</div><div class="row" style="width:100%;max-width:340px"><button class="btn" data-act="skipOb" style="flex:1">Skip</button><button class="btn p" data-act="nextOb" data-p="${i}" style="flex:2">${i===2?'Get started':'Next'}</button></div></div>`},
terms:()=>tb('Terms')+`<div class="card col sm muted"><a class="btn p full" data-legal="1" href="${LEGAL_URL}terms.html" target="_blank" rel="noopener" style="margin-bottom:12px">📄 Open full Terms &amp; Conditions</a><p><b>Rewards.</b> Rewards are credited only after each submission is reviewed and approved. We may adjust or decline a reward if the task was not completed as described.</p><p><b>Fair use.</b> Do not submit false or duplicate proof, use more than one account, or use bots or scripts. Accounts that break these rules can be blocked and unpaid balances cancelled.</p><p><b>Withdrawals.</b> You can request a withdrawal once your balance reaches the minimum shown in your Wallet. Requests are reviewed before payment, and payment goes to the UPI or bank details you added.</p><p><b>No guarantee.</b> Earnings are not guaranteed and depend on available tasks. ${esc(appName())} is not a bank and does not offer investments or loans.</p><p><b>Third parties.</b> Tasks may open other apps or websites. They have their own terms and are not controlled by us.</p><p>Full terms online: <a data-legal="1" href="${LEGAL_URL}terms.html" target="_blank" rel="noopener" style="color:var(--secondary);overflow-wrap:anywhere">${LEGAL_URL}terms.html</a></p><a class="btn p full" data-legal="1" href="${LEGAL_URL}" target="_blank" rel="noopener" style="margin-bottom:12px">🔒 Open Privacy Policy</a></div>`,
privacy:()=>tb('Privacy')+`<div class="card col sm muted"><a class="btn p full" data-legal="1" href="${LEGAL_URL}" target="_blank" rel="noopener" style="margin-bottom:12px">🔒 Open full Privacy Policy</a><p><b>What we collect.</b> Your name, email, phone number, optional profile photo, referral code, task submissions (proof), wallet and transaction history, and the UPI or bank details you add for payouts. Your password is handled by Firebase Authentication and we cannot see it.</p><p><b>Why.</b> To run your account, review tasks, pay withdrawals, prevent fraud and duplicate accounts, and give support.</p><p><b>Where it is stored.</b> On Google Firebase servers (Authentication and Realtime Database), and some settings are saved on your device.</p><p><b>Sharing.</b> We do not sell your data. We share it only with service providers needed to run the app (such as Google Firebase) or when the law requires it.</p><p><b>Permissions.</b> The app needs internet access. It does not ask for your contacts, SMS or location.</p><p><b>Delete your data.</b> Email junaidbhai781@gmail.com or message +91 95681 53948 on WhatsApp and we will delete your account and data.</p><p>Full policy online: <a data-legal="1" href="${LEGAL_URL}" target="_blank" rel="noopener" style="color:var(--secondary);overflow-wrap:anywhere">${LEGAL_URL}</a></p><a class="btn p full" data-legal="1" href="${LEGAL_URL}terms.html" target="_blank" rel="noopener" style="margin-bottom:12px">📄 Open Terms &amp; Conditions</a></div>`,
rewards:()=>{const lv=level();return tb('Levels & rewards')+`<div class="col">${LEVELS.map((n,i)=>`<div class="card row"><div class="ti">${['🥉','🥈','🥇','💠','💎'][i]}</div><div class="mid" style="flex:1"><b>Level ${i+1} · ${n}</b><div class="muted sm">${i*1000} XP${i+1>1?' · unlocks harder, higher-paying tasks':''}</div></div>${lv>i+1?'<span class="chip ok">Done</span>':lv===i+1?'<span class="chip wa">Current</span>':'<span class="chip">Locked</span>'}</div>`).join('')}</div><button class="btn full" style="margin-top:12px" data-go="leaders">View leaderboard</button>`},
};

